(ns fastmath.transform-test
  (:require [fastmath.transform :as sut]
            [fastmath.vector :as v]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn])
  (:import [fastmath.vector Vec2]))

;; Reference values from numpy / scipy (`scipy.fft`, `scipy.linalg.hadamard`), generated by
;; `utils/fastmath/dev/generate_transform_reference.py` into
;; `test/resources/transform/fourier_reference.edn`: lengths 1, 2, 3, 5, 8, 15, 16, 17,
;; norms :backward, :ortho, :forward, 2d arrays 4x6, 5x3, 1x4, 3x1.

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "transform/fourier_reference.edn")))))

(defn- ->vec2s [pairs] (mapv (fn [[re im]] (Vec2. re im)) pairs))
(defn- vec2s->pairs [zs] (mapv (fn [^Vec2 z] [(.x z) (.y z)]) zs))

(defn- close?
  "Max absolute difference not above 1e-13 times (1 + max |reference|): values are up to ~100."
  [expected actual]
  (let [e (flatten (seq expected))
        a (flatten (seq actual))]
    (and (= (count e) (count a))
         (let [scale (inc (reduce max 0.0 (map #(Math/abs (double %)) e)))]
           (every? (fn [[^double x ^double y]] (<= (Math/abs (- x y)) (* 1.0e-13 scale))) (map vector e a))))))

(def ^:private norms [:backward :ortho :forward])

(t/deftest fourier-vs-numpy
  (doseq [{:keys [n x z] :as e} (:one-d @reference)
          norm norms
          :let [r (e norm)
                zs (->vec2s z)]]
    (t/testing (str "N=" n " " norm)
      (t/is (close? (:rfft r) (vec2s->pairs (sut/fft x {:norm norm}))) "single-sided")
      (t/is (close? (:fft r) (vec2s->pairs (sut/fft x {:norm norm :spectrum :double-sided}))) "double-sided")
      (t/is (close? (:cfft r) (vec2s->pairs (sut/fft zs {:norm norm}))) "complex input")
      (t/is (close? (:ifft r) (vec2s->pairs (sut/ifft zs {:kind :complex :norm norm}))) "complex inverse"))))

(t/deftest fourier-round-trips
  (doseq [{:keys [x z]} (:one-d @reference)
          norm norms
          :let [n (count x)
                zs (->vec2s z)]]
    (t/testing (str "N=" n " " norm)
      (let [X (sut/fft x {:norm norm})]
        (t/is (= {:kind :real :n n :norm norm} (::sut/fft (meta X))))
        (t/is (= (inc (quot n 2)) (count X)))
        (t/is (close? x (sut/ifft X)) "with metadata")
        (t/is (close? x (sut/ifft (vec X) {:kind :real :n n :norm norm})) "explicit options")
        (t/is (vector? (sut/ifft X))))
      (let [X (sut/fft x {:norm norm :spectrum :double-sided})]
        (t/is (= {:kind :complex :n n :norm norm :real? true} (::sut/fft (meta X))))
        (t/is (close? x (sut/ifft X)) "double-sided with metadata")
        (t/is (close? x (sut/ifft (vec X) {:kind :complex :real? true :norm norm})) "double-sided explicit"))
      (let [Z (sut/fft zs {:norm norm})]
        (t/is (= {:kind :complex :n n :norm norm :real? false} (::sut/fft (meta Z))))
        (t/is (close? z (vec2s->pairs (sut/ifft Z))) "complex with metadata")
        (t/is (every? #(instance? Vec2 %) (sut/ifft Z)))))))

(t/deftest cosine-sine-vs-scipy
  (doseq [{:keys [n x] :as e} (:one-d @reference)
          norm norms
          t [1 2 3]
          :let [r (e norm)
                method-c (keyword (str "DCT-" (apply str (repeat t "I"))))
                method-s (keyword (str "DST-" (apply str (repeat t "I"))))]]
    (t/testing (str "N=" n " " norm " type " t)
      (when-not (and (= t 1) (< n 2))
        (t/is (close? (r (keyword (str "dct" t))) (sut/dct x {:method method-c :norm norm})))
        (t/is (close? (r (keyword (str "idct" t))) (sut/idct x {:method method-c :norm norm})))
        (t/is (close? x (sut/idct (sut/dct x {:method method-c :norm norm}))) "dct round trip"))
      (t/is (close? (r (keyword (str "dst" t))) (sut/dst x {:method method-s :norm norm})))
      (t/is (close? (r (keyword (str "idst" t))) (sut/idst x {:method method-s :norm norm})))
      (t/is (close? x (sut/idst (sut/dst x {:method method-s :norm norm}))) "dst round trip"))))

(t/deftest cosine-sine-defaults-and-metadata
  (let [x [1.0 -2.0 3.5 0.25 4.0]
        c (sut/dct x)
        s (sut/dst x)]
    (t/is (= {:method :DCT-II :norm :ortho} (::sut/dct (meta c))))
    (t/is (= {:method :DST-II :norm :ortho} (::sut/dst (meta s))))
    (t/is (vector? c))
    (t/is (close? x (sut/idct c)))
    (t/is (close? x (sut/idct (vec c))) "no metadata: defaults :DCT-II :ortho")
    (t/is (close? x (sut/idst (vec s))) "no metadata: defaults :DST-II :ortho")
    (t/is (close? x (sut/idct (vec (sut/dct x {:method :DCT-I :norm :backward}))
                              {:method :DCT-I :norm :backward})))))

(t/deftest hartley-vs-numpy
  (doseq [{:keys [n x] :as e} (:one-d @reference)
          norm norms
          :let [r (e norm)]]
    (t/testing (str "N=" n " " norm)
      (t/is (close? (:dht r) (sut/dht x {:norm norm})))
      (t/is (close? (:idht r) (sut/idht x {:norm norm})))
      (t/is (close? x (sut/idht (sut/dht x {:norm norm}))) "round trip with metadata"))))

(t/deftest hadamard-vs-scipy
  (doseq [{:keys [x hadamard]} (:one-d @reference)
          :when hadamard]
    (t/is (close? hadamard (sut/hadamard x)))
    (t/is (vector? (sut/hadamard x)))
    (t/is (close? x (sut/ihadamard (sut/hadamard x))))))

(defn- array->rows [^"[[D" arr] (mapv vec arr))

(t/deftest two-d-transforms
  (doseq [{:keys [rows cols x fft2 dht2]} (:two-d @reference)
          :when (and (> rows 1) (> cols 1))]
    (t/testing (str rows "x" cols)
      (let [cfft (sut/transformer :complex :fft)
            cfftr (sut/transformer :complex :fftr)
            dht (sut/transformer :real :dht)
            interleaved (mapv (fn [r] (vec (mapcat (fn [v] [v 0.0]) r))) x)]
        (t/is (instance? (Class/forName "[[D") (sut/forward-2d cfftr x)))
        (t/is (close? fft2 (map #(partition 2 %) (array->rows (sut/forward-2d cfft interleaved)))) "complex 2d")
        (t/is (close? fft2 (map #(partition 2 %) (array->rows (sut/forward-2d cfftr x)))) "real input, full spectrum")
        (t/is (close? fft2 (map #(partition 2 %) (array->rows (sut/forward-2d cfft interleaved {:scale? true})))) "options arity")
        (t/is (close? interleaved (array->rows (sut/reverse-2d cfft (sut/forward-2d cfft interleaved)))) "complex round trip")
        (t/is (close? interleaved (array->rows (sut/reverse-2d cfft (sut/forward-2d cfft interleaved) {:scale? true}))))
        (t/is (close? dht2 (array->rows (sut/forward-2d dht x))) "dht 2d")
        (t/is (close? x (array->rows (sut/reverse-2d dht (sut/forward-2d dht x)))) "dht round trip"))))
  (t/testing "JTransforms 2d limits: more than one row and column; real packed FFT needs power-of-two sizes"
    (doseq [{:keys [rows cols x]} (:two-d @reference)
            :when (or (== rows 1) (== cols 1))]
      (t/is (thrown? IllegalArgumentException (sut/forward-2d (sut/transformer :complex :fftr) x))))
    (t/is (thrown? IllegalArgumentException (sut/forward-2d (sut/transformer :real :fft) (repeat 4 (range 6)))))
    (let [rfft (sut/transformer :real :fft)
          x (mapv (fn [r] (mapv (fn [c] (Math/sin (+ (* 0.7 r) (* 1.3 c c)))) (range 8))) (range 4))]
      (t/is (close? x (array->rows (sut/reverse-2d rfft (sut/forward-2d rfft x)))) "real packed round trip 4x8"))))

(t/deftest raw-transformers
  (let [x [1.0 2.0 -1.0 0.5 3.0 -2.0 0.0 1.5]]
    (t/testing "real fft raw packed layout: [Re0 Re(N/2) Re1 Im1 ...]"
      (let [packed (vec (sut/forward-1d (sut/transformer :real :fft) x))
            X (sut/fft x)]
        (t/is (close? [(.x ^Vec2 (first X)) (.x ^Vec2 (last X))] (take 2 packed)))
        (t/is (close? x (sut/reverse-1d (sut/transformer :real :fft) packed)))))
    (t/testing "hadamard accepts options arity"
      (t/is (close? (sut/hadamard x) (sut/forward-1d (sut/transformer :real :hadamard) x {}))))
    (t/testing "ACM sine/cosine transformers"
      (let [s (sut/transformer :real :sine)
            c (sut/transformer :real :cosine)
            xs (assoc x 0 0.0)
            xc (conj x 1.0)]
        (t/is (close? xs (sut/reverse-1d s (sut/forward-1d s xs))))
        (t/is (close? xc (sut/reverse-1d c (sut/forward-1d c xc {:normalization :standard}) {:normalization :standard})))
        (t/is (close? xc (sut/reverse-1d (sut/transformer :cosine :orthogonal)
                                         (sut/forward-1d (sut/transformer :cosine :orthogonal) xc))))))))

(t/deftest guards
  (t/testing "empty input"
    (doseq [f [sut/fft sut/dct sut/dst sut/dht sut/idct sut/idst sut/idht sut/hadamard sut/ihadamard
               #(sut/ifft % {:kind :complex})]]
      (t/is (thrown? clojure.lang.ExceptionInfo (f [])))
      (t/is (thrown? clojure.lang.ExceptionInfo (f nil))))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/forward-1d (sut/transformer :real :fft) [])))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/forward-2d (sut/transformer :real :fft) []))))
  (t/testing "ifft needs kind and length"
    (let [X (vec (sut/fft [1 2 3 4]))]
      (t/is (thrown? clojure.lang.ExceptionInfo (sut/ifft X)) "no metadata, no :kind")
      (t/is (thrown? clojure.lang.ExceptionInfo (sut/ifft X {:kind :real})) "no :n")
      (t/is (thrown? clojure.lang.ExceptionInfo (sut/ifft X {:kind :real :n 7})) "wrong :n")
      (t/is (close? [1 2 3 4] (sut/ifft X {:kind :real :n 4})))
      (t/is (close? [1 2 3 4 5] (sut/ifft (vec (sut/fft [1 2 3 4 5])) {:kind :real :n 5})) "odd length")
      (t/is (thrown? clojure.lang.ExceptionInfo (sut/ifft X {:kind :half})))))
  (t/testing "unknown options"
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/fft [1 2] {:norm :none})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/fft [1 2] {:spectrum :both})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/dct [1 2] {:method :DCT-IV})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/dct [1 2] {:norm :none})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/dst [1 2] {:method :DST-IV})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/dht [1 2] {:norm :none})))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/transformer :unknown :fft)))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/transformer :real :dft)))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/transformer :complex :dht)))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/transformer :sine :fast)))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/forward-1d (sut/transformer :real :sine) [0 1 2 3] {:normalization :x}))))
  (t/testing "input shape"
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/dct [1.0] {:method :DCT-I})) "DCT-I needs 2 values")
    (t/is (close? [2.0] (sut/dct [1.0] {:method :DCT-II :norm :backward})) "one value")
    (t/is (close? [2.0] (sut/dst [1.0] {:method :DST-I :norm :backward})) "one value")
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/hadamard [1 2 3])))
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/forward-1d (sut/transformer :complex :fft) [1 2 3])) "odd interleaved length")
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/fft [(v/vec3 1 2 3)])) "neither number nor Vec2")
    (t/is (thrown? clojure.lang.ExceptionInfo (sut/forward-2d (sut/transformer :real :hadamard) [[1 2] [3 4]])) "no 2d")))
